ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT));import nfl_lab
from tools import category_topfive_matched12_storage_v1 as st
OUT=ROOT/'reports/category-topfive-matched-all12-w1w7-20261030'
ORDER=['pass_yd','pass_td','pass_cmp','pass_att','pass_int','rush_yd','rush_att','rec','rec_yd','rush_rec_yd','anytime_td','chart_ppr']
NAMES=dict(zip(ORDER,['Passing yards','Passing TDs','Completions','Passing attempts','Interceptions','Rushing yards (RB)','Carries (RB)','Receptions','Receiving yards','Rushing + receiving yards','Anytime rushing/receiving TD','Chart PPR']))
def readgz(name):return json.loads(gzip.decompress((OUT/name).read_bytes()))
def ratio(s):
 if not s or not s.get('decided'):return 'Unavailable'
 return f"{s['wins']}/{s['decided']} ({100*s['hit_rate']:.1f}%)"
def main():
 p=json.loads(gzip.decompress((ROOT/'config/category-topfive-matched12-all-finalists-grade-v1.json.gz').read_bytes()))
 forward=Path(st.prepare(ROOT)['allocation']['store_policy']['storage']['forward_root'])
 with zipfile.ZipFile(forward/'research'/p['run_id']/'RESULTS.zip') as z:
  raw=z.read('AGGREGATES.json.gz');assert hashlib.sha256(raw).hexdigest()=='2275410cce9a7ae7937f3b03ffc0e264534a4b55c09ab93fe9b7f2f15fcfee5c';a=json.loads(gzip.decompress(raw))
 leaders={x['category']:x for x in readgz('OBSERVED_OBJECTIVE_LEADERS_POINT_V1.json.gz')['point']}
 ranks=list(csv.DictReader(io.StringIO(gzip.decompress((OUT/'RESEARCH_POINT_PROCEDURE_RANKING_W1_7.csv.gz').read_bytes()).decode())))
 old=json.loads((ROOT/'reports/next-nfl-checkpoint-20261028/LOWEST_PRODUCTION_OWNER_CATALOG_DRAFT_V1.json').read_bytes())
 old={x['category']:x for x in old['rows']}
 audit=json.loads((ROOT/'reports/category-topfive-mae-release-priority-20261030/CURRENT_SERVED_AUDIT_V3.json').read_bytes());audit={x['category']:x for x in audit['categories']}
 records=[];lines=['# Matched twelve-category comparison — 2026 Weeks 1–7','','**Current-season point/P1 comparison and 24-law replay completed; historical same-finalist extensions and owner release remain unfinished.** This is exposed historical development, with current-vintage inputs and the preserved seven-day availability assumption. These are not forecasts originally issued before these games.','','## Current-season category decisions','','MAE means the average absolute miss, in yards, counts or chart points. The Over/Under columns below belong to the listed **point leader**, using its unrounded point against the original recorded line. They are statistical direction counts on the supported offered subset, not venue-settled returns. The numerical-MAE population is broader.','','| Category | Lowest observed point procedure | MAE / probability loss | Scored player-games | Lower MAE versus base CDF | Its Over correct/decided | Its Under correct/decided | Current served family/product |','|---|---|---:|---:|---:|---:|---:|---|']
 for target in ORDER:
  x=leaders[target];o=old.get(target,{});live=audit.get(target);s=x.get('own_P1_sides') or {};cat=a['catalog'][target][x['method']]
  if live:
   assert live['model_versions']['exact_values']==o['actual_selected_versions'] and live['procedure_versions']['exact_values']==o['actual_selected_procedures']
   active={'family_binding':o['selected_families'],'method_id':'P2_SELECTED','model_versions':live['model_versions']['exact_values'],'procedure_versions':live['procedure_versions']['exact_values'],'products':live['product_functionals'],'served_rows':live['selected_rows'],'issue_date':'2026-10-28','new_MAE_release':False}
  else:active={'family_binding':None,'status':'OLD_SCORING_FALLBACK_NOT_NICK_CHART_PPR_V1','new_MAE_release':False}
  choices=[r for r in ranks if r['category']==target]
  if target=='anytime_td':choices=[{'method':m,'products':v['products'],'procedure_version':v['procedure_version']} for m,v in a['catalog'][target].items() if m!='LEAF_CDF_RAW_ORIGINAL_EVENT']
  rec={'category':target,'current_season_point_recommendation':{k:x[k] for k in ['method','product','procedure_version','same_core_scored','MAE','MSE_or_ATD_Brier','paired_control_loss','candidate_minus_CDF_control','improvement_percent_vs_named_CDF_NOT_SITE','game_CI_lower','game_CI_upper','week_CI_lower','week_CI_upper']},'model_binding':cat,'five_procedure_research_ranking':choices,'expected_mean_recommendation':x.get('best_mean'),'own_point_side_results':s,'highest_observed_Over':x.get('observed_over_leader'),'highest_observed_Under':x.get('observed_under_leader'),'actual_served':active,'release_state':'RECOMMENDED_RESEARCH_TARGET_NOT_NEW_PRODUCTION_SELECTION','policy':'stat_point_mae_v2; reconcile exact current-season candidate under retained owner policy; probability/EV independent','operational_dependency':'Retained owner current source/model/wrapper restoration, typed output admission, future inference, immutable pregame persistence, fallback/rollback and actual served consumption. Do not substitute base CDF for ordered/backfield/response identity.','point_contract':'selected_projection distinct from independently selected expected mean and probabilities','new_current_query_capture':0,'new_live_release':0}
  if target=='anytime_td':rec['operational_dependency']='Keep existing probability release unchanged until separate probability policy admission; late Platt contender is a separately scored development appendix, not original frozen fifth.'
  if target=='chart_ppr':rec['operational_dependency']='Exact nick-chart-ppr-v1 sixteen-component future-source, typed adapter, restoration, participation and consumer migration; legacy PPR fallback retains old identity.'
  records.append(rec)
  value=f"Brier {x['MSE_or_ATD_Brier']:.6f}" if target=='anytime_td' else f"{x['MAE']:.4f}"
  delta='Separate probability objective' if target=='anytime_td' else f"{x['improvement_percent_vs_named_CDF_NOT_SITE']:.3f}%"
  current='/'.join(o.get('selected_families',[]))+' '+o.get('functional','') if live else 'Legacy fallback; chart not active'
  lines.append(f"| {NAMES[target]} | {x['method']} / {x['product']} | {value} | {x['same_core_scored']} | {delta} | {ratio(s.get('over'))} | {ratio(s.get('under'))} | {current} |")
 lines += ['','The clearest numeric difference is carries: 3.628 versus 3.758, a 0.1297-carry decrease. Its paired game-cluster interval is approximately −0.1993 to −0.0652 carries; week-cluster interval −0.1741 to −0.0898. Most other leads are tiny and their paired intervals cross zero. Chart response-CDF improves by 0.0216 points on this panel. All periods have been inspected; the shortlist and output choice introduce selection uncertainty. These are comparisons with the named laboratory CDF, **not proven percentage gains over the actual live website**.','','## Five procedures per category and every output','','[Ranked numeric procedure shortlist](RESEARCH_POINT_PROCEDURE_RANKING_W1_7.csv) · [All point products, errors, bias, tails, coverage and paired uncertainty](POINT_PRODUCTS_W1_7.csv) · [Every method/output’s own Over/Under record](EACH_POINT_PRODUCTS_OWN_OVER_UNDER_W1_7.csv) · [Weekly own-side records](EACH_POINT_PRODUCTS_OWN_OVER_UNDER_BY_WEEK.csv.gz) · [Complete immutable main aggregates](ALL_FINALISTS_AGGREGATES_V1.json.gz).','','| Category | Five meaningful procedure groups (point-MAE order; output variants share one group) |','|---|---|']
 for target in ORDER:
  names=[x['method'] for x in records[ORDER.index(target)]['five_procedure_research_ranking']]
  if target=='anytime_td':names=['Normalized leaf CDF','CatBoost binary','Equal CDF/CatBoost probability blend','Role logistic','Retained Platt curve — late entrant, separate appendix']
  lines.append('| '+NAMES[target]+' | '+', '.join(names)+' |')
 lines += ['','Legacy Count A empirical points and corrected stored means remain separate outputs of the same family. The yardage three-way point blend is the declared equal CDF/CatBoost/HGB recipe, not an old P4 recipe or the median of a mixture distribution. Response-CDF, ordered CDF and backfield CDF have distinct procedure/source bindings. The depth passing-attempt comparator has only Weeks 1–6 and remains a secondary partial record; it does not shrink the full Weeks 1–7 headline core.','','## Mean, law, probability and selection products','','Mean MSE/RMSE leaders are retained separately in the release manifest; they are not automatically the means of the displayed model. Valid saved laws provide CRPS, threshold probabilities, pushes and direct log-tail loss. Count A/CatBoost point objectives do not create an assumed PMF. Numeric threshold Brier uses one-half of the sum over Under/Push/Over outcomes; conditional market comparisons use a separate binary score. Anytime TD retains Brier as primary.','','Full board, Top 6/10/20, confidence-abstaining, always-side, disagreement and paired game/week-aware comparisons are retained. Own Over rates compare different selected subsets; a 4/5 result is not stronger evidence than a much larger sample. The highest retrospective Over and Under performers are never spliced into a historical strategy. Original website recommendations remain in [their separate immutable report](../category-topfive-original-leans-release-ou-20261030/README.md).','','## Scope, labels and coverage','','All 107 scheduled games are represented (16/16/16/16/15/14/14); 4,985 qualified roster queries were attempted and 502 source identity rows quarantined. Full finalist grading materialized 283,673 product rows, with 188 missing depth outputs; these are repeated procedure/product incidences. There were 124,110 supported scored incidences in the primary-role population, not that many independent football games.','','The exact outcome version contains 43,470 target-label opportunities including forecast-only targets. Passing labels support 241 played QB cases of 718 queried; RB rushing supports 586 of 1,244; receiving/ATD supports 2,000 of 4,267; chart supports 2,241 of 4,985. Unknown participation stays unknown, never zero or DNP. The source-qualified chart uses signed official yards and all sixteen specified primitives. Week 8 outcomes were not admitted. Full system missingness and fallback counts appear alongside the common supported core.','','The recorded board has 3,998 unique primary lines: 2,705 in Weeks 1–5, 676 in Week 6 and 617 in Week 7. Quote clocks and venue participation/settlement rules remain unqualified. Statistical direction can be scored; authenticated historical execution cannot be claimed. Targets and chart have no qualified actual offers. Anytime TD is a separate event target.','','## Market evidence and limits','','The archive contains 2,642 valid same-book/same-line two-sided price pairs, only in Weeks 1–5. An independent-book, same-naive-collection-clock reference supports 1,068 opportunities before outcome qualification. Offering-book exclusion is preserved. No historical quote clock, original cutoff or settlement contract is established. Week 6–7 lines have no prices; ATD Yes prices do not identify fair No probabilities. No −110 defaults, manufactured offers, EV/ROI or profitability claims are used. The fixed-half hybrid and line-as-point heuristic are exploratory and reported separately.','','## What actually ran and was checked','','Twenty-five successful new fitted models were saved: nine HGB, thirteen missing fixed Count A/CatBoost/response cells and three chart/event models. Two chart/event resource failures remain visible; the failed response and logistic cells were retried in isolated fresh processes without rerunning the successful CatBoost. Retained-model restorations, 283,485 frozen output rows, later materialized missing rows, scoring runs and NFL outcomes are distinct counts.','','Independent grading checked the main point/side arithmetic and all 24 cached law packages. Law QA covered 77,594 distribution rows, 16,892 line-probability records and 308 policy records; only sixteen outcome-blind query slots were independently re-inferred, with nine supported CRPS outcomes. This is not complete independent re-inference of every vector. [Main QA](primary-scoring/INDEPENDENT_FRESH_QA_ALL_FINALISTS_V1.json) · [Law QA](law-qa/ACTUAL_INDEPENDENT_QA_V1.json).','','[Readable private scorecard receipt](READABLE_PRIVATE_SCORECARD_V1.json): 204,431 prediction/actual CSV rows and 258,748 line/direction CSV rows, exact ZIP readback. These remain restricted private evidence; approved owner restoration is required. No player-level raw data are placed in this public repository.','','## Historical seasons and training histories','','Current models generally use earlier multiseason training through 2025; chart models use admitted 2024 chart labels. Best on 2026 does not mean trained only on 2026. The old 2025 ordered-history and 2022–2024 benchmarks remain intact, including negative findings. Their populations, source timing and feature treatment can differ from this repaired panel. They are not silently copied into a matched same-finalist tournament. Missing same-contract historical cells and clean H-CURRENT/H-RECENT/H-MULTI cells remain unfinished; no through-2025 model is applied to its own 2025 outcomes as out-of-sample evidence.','','## Production, capture and exact remaining owner action','','**This session is research-only.** Website Main remains `1ec93e068a91abd51c990937d1019e4a831694b4`; no later owner acknowledgement was returned by the October 30 late-evening read. The served payload SHA is `369fec9caec012cb292284006a60bb25727d6d9d853f00560dbffe57f1ea1fa4`: 1,945 forecasts issued October 28, zero new MAE-profile rows. [Live readback](LIVE_READBACK_V1.json) · [Category release manifest](CATEGORY_RELEASE_MANIFEST_V2.json.gz). The exact live family/procedure/model bindings are recorded; chart PPR is not active.','','The retained owner holds lease 178. The ready release package at commit `341742de83975264a07d035d4b6289e57c2ec1e9` was delivered, not acknowledged or executed. It must restore parent `40729788942` / child `40729906573`, authenticate SOURCE/query-completion/feature-capture receipts and actual model/wrapper/slot bindings, admit separately typed selected_projection while preserving independent means/probabilities, perform current-query inference, immutable persistence, fallback/rollback and publish/read back the actual consumer. Newly tested response, ordered/backfield, target and chart adapters retain their own guards. Ready older core products do not wait for this new research package.','','Next configured parent: **October 31, 7:36–7:57 a.m. CDT**. Next remaining Sunday T−90: **November 1, 10:30 a.m. CST**. These are future configured actions, not completed capture. The last inspected parent `41104520104` failed with capture enqueue skipped. Original assignments and the per-method Week 8 census still require approved owner-controlled restoration. No capture was backdated and no older issue time was replaced.','','## Reproducible records and next executable work','','[Registration](EXECUTION_PROTOCOL_V1.json) · [Finalist/source amendments](FINALIST_AMENDMENTS_V1_1.json) · [Population/contracts](POPULATION_AND_PRODUCT_AMENDMENTS_V1.json) · [Canonical project index](../opportunity-four/README.md). Source configurations, models, source snapshots and full row vectors stay in the approved managed store; public code, aggregate scores and safe hashes provide the evidence index. Local-only artifacts remain PUBLICATION_PENDING until exact remote readback. Original caps, exhausted allocations, failures, losing weeks and scientific registrations are preserved. Lossless metadata compression stayed within the same accounting; no unique source/model/vector was discarded.','','Finish the late ATD supplement and exploratory M/H independent check; publish every result with remote readback; complete compatible historical cells under finite registrations; continue the four-category information backlog independently of owner-only release. No probability or EV ranking is activated solely from lower point MAE.']
 (OUT/'CATEGORY_RELEASE_MANIFEST_V2.json.gz').write_bytes(gzip.compress(json.dumps({'version':'matched12-category-research-targets-v2','state':'RESEARCH_RECOMMENDATIONS_NOT_DEPLOYMENT','source_result_sha256':'5e30c74d98b07acc76cd54a7731570f4f9e4b5843c970a69ae30996cea00fe77','categories':records},separators=(',',':'),allow_nan=False).encode(),mtime=0))
 (OUT/'README.md').write_text('\n'.join(lines)+'\n')
 print(json.dumps({'categories':len(records),'report_bytes':(OUT/'README.md').stat().st_size,'manifest_gzip_bytes':(OUT/'CATEGORY_RELEASE_MANIFEST_V2.json.gz').stat().st_size,'new_scores_fits':0}))
if __name__=='__main__':main()
